import{_ as a,a0 as d,w as c,s as l,ao as r,I as s,x as t,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services","title":"RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services.md","filePath":"[post].md"}'),i={name:"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services.md"};function m(S,e,h,w,u,H){const n=d("Link");return c(),l("div",null,[e[17]||(e[17]=r(`<h1 id="rhcsa-系列-八-加固-ssh-设定主机名及启用网络服务" tabindex="-1">RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务 <a class="header-anchor" href="#rhcsa-系列-八-加固-ssh-设定主机名及启用网络服务" aria-label="Permalink to “RHCSA 系列（八）: 加固 SSH，设定主机名及启用网络服务”">​</a></h1><p>作为一名系统管理员，你将经常使用一个终端模拟器来登录到一个远程的系统中，执行一系列的管理任务。你将很少有机会坐在一个真实的（物理）终端前，所以你需要设定好一种方法来使得你可以登录到你需要去管理的那台远程主机上。</p><p>事实上，当你必须坐在一台物理终端前的时候，就可能是你登录到该主机的最后一种方法了。基于安全原因，使用 Telnet 来达到以上目的并不是一个好主意，因为穿行在线缆上的流量并没有被加密，它们以明文方式在传送。</p><p>另外，在这篇文章中，我们也将复习如何配置网络服务来使得它在开机时被自动开启，并学习如何设置网络和静态或动态地解析主机名。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Secure-SSH-Server-and-Enable-Network-Services.png" alt="RHCSA: 安全 SSH 和开启网络服务"></p><p><em>RHCSA: 安全 SSH 和开启网络服务 – Part 8</em></p><h3 id="安装并确保-ssh-通信安全" tabindex="-1">安装并确保 SSH 通信安全 <a class="header-anchor" href="#安装并确保-ssh-通信安全" aria-label="Permalink to “安装并确保 SSH 通信安全”">​</a></h3><p>对于你来说，要能够使用 SSH 远程登录到一个 RHEL 7 机子，你必须安装 <code>openssh</code>，<code>openssh-clients</code> 和 <code>openssh-servers</code> 软件包。下面的命令不仅将安装远程登录程序，也会安装安全的文件传输工具以及远程文件复制程序：</p><pre><code># yum update &amp;&amp; yum install openssh openssh-clients openssh-servers
</code></pre><p>注意，也安装上服务器所需的相应软件包是一个不错的主意，因为或许在某个时刻，你想使用同一个机子来作为客户端和服务器。</p><p>在安装完成后，如若你想安全地访问你的 SSH 服务器，你还需要考虑一些基本的事情。下面的设定应该出现在文件 <code>/etc/ssh/sshd_config</code> 中。</p><p>1、 更改 sshd 守护进程的监听端口，从 22（默认的端口值）改为一个更高的端口值（2000 或更大），但首先要确保所选的端口没有被占用。</p>`,12)),s("p",null,[e[1]||(e[1]=t("例如，让我们假设你选择了端口 2500 。使用 ",-1)),o(n,{href:"http://www.tecmint.com/20-netstat-commands-for-linux-network-management/"},{default:p(()=>[...e[0]||(e[0]=[t("netstat",-1)])]),_:1}),e[2]||(e[2]=t(" 来检查所选的端口是否被占用：",-1))]),e[18]||(e[18]=r(`<pre><code># netstat -npltu | grep 2500
</code></pre><p>假如 netstat 没有返回任何信息，则你可以安全地为 sshd 使用端口 2500，并且你应该在上面的配置文件中更改端口的设定，具体如下：</p><pre><code>Port 2500
</code></pre><p>2、 只允许协议 2（LCTT 译注：SSHv1 已经被证明不安全，默认情况下 SSHv1 和 SSHv2 都支持，所以应该显示去掉如下配置行的注释，并只支持 SSHv2。）：</p><pre><code>Protocol 2
</code></pre><p>3、 配置验证超时的时间为 2 分钟，不允许以 root 身份登录，并将允许通过 ssh 登录的人数限制到最小：</p><pre><code>LoginGraceTime 2m
PermitRootLogin no
AllowUsers gacanepa
</code></pre><p>4、 假如可能，使用基于公钥的验证方式而不是使用密码：</p><pre><code>PasswordAuthentication no
RSAAuthentication yes
PubkeyAuthentication yes
</code></pre><p>这假设了你已经在你的客户端机子上创建了带有你的用户名的一个密钥对，并将公钥复制到了你的服务器上。</p>`,10)),s("ul",null,[s("li",null,[o(n,{href:"https://linux.cn/article-5444-1.html"},{default:p(()=>[...e[3]||(e[3]=[t("开启 SSH 无密码登录",-1)])]),_:1})])]),e[19]||(e[19]=r(`<h3 id="配置网络和名称的解析" tabindex="-1">配置网络和名称的解析 <a class="header-anchor" href="#配置网络和名称的解析" aria-label="Permalink to “配置网络和名称的解析”">​</a></h3><p>1、 每个系统管理员都应该对下面这个系统配置文件非常熟悉：</p><ul><li>/etc/hosts 被用来在小型网络中解析“名称” &lt;---&gt; “IP 地址”。</li></ul><p>文件 <code>/etc/hosts</code> 中的每一行拥有如下的结构：</p><pre><code>IP address - Hostname - FQDN
</code></pre><p>例如，</p><pre><code>192.168.0.10    laptop  laptop.gabrielcanepa.com.ar
</code></pre><p>2、 <code>/etc/resolv.conf</code> 特别指定 DNS 服务器的 IP 地址和搜索域，它被用来在没有提供域名后缀时，将一个给定的查询名称对应为一个全称域名。</p><p>在正常情况下，你不必编辑这个文件，因为它是由系统管理的。然而，若你非要改变 DNS 服务器的 IP 地址，建议你在该文件的每一行中，都应该遵循下面的结构：</p><pre><code>nameserver - IP address
</code></pre><p>例如，</p><pre><code>nameserver 8.8.8.8
</code></pre><p>3、 <code>/etc/host.conf</code> 特别指定在一个网络中主机名被解析的方法和顺序。换句话说，告诉名称解析器使用哪个服务，并以什么顺序来使用。</p><p>尽管这个文件由几个选项，但最为常见和基本的设置包含如下的一行：</p><pre><code>order bind,hosts
</code></pre><p>它意味着解析器应该首先查看 <code>resolv.conf</code> 中特别指定的域名服务器，然后到 <code>/etc/hosts</code> 文件中查找解析的名称。</p><p>4、 <code>/etc/sysconfig/network</code> 包含了所有网络接口的路由和全局主机信息。下面的值可能会被使用：</p><pre><code>NETWORKING=yes|no
HOSTNAME=value
</code></pre><p>其中的 value 应该是全称域名（FQDN）。</p><pre><code>GATEWAY=XXX.XXX.XXX.XXX
</code></pre><p>其中的 XXX.XXX.XXX.XXX 是网关的 IP 地址。</p><pre><code>GATEWAYDEV=value
</code></pre><p>在一个带有多个网卡的机器中， value 为网关设备名，例如 enp0s3。</p><p>5、 位于 <code>/etc/sysconfig/network-scripts</code> 中的文件（网络适配器配置文件）。</p><p>在上面提到的目录中，你将找到几个被命名为如下格式的文本文件。</p><pre><code>ifcfg-name
</code></pre><p>其中 name 为网卡的名称，由 <code>ip link show</code> 返回：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-IP-Address.png" alt="检查网络连接状态"></p><p><em>检查网络连接状态</em></p><p>例如：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Network-Files.png" alt="网络文件"></p><p><em>网络文件</em></p><p>除了环回接口（loopback），你还可以为你的网卡指定相似的配置。注意，假如设定了某些变量，它们将为这个指定的接口覆盖掉 <code>/etc/sysconfig/network</code> 中定义的默认值。在这篇文章中，为了能够解释清楚，每行都被加上了注释，但在实际的文件中，你应该避免加上注释：</p><pre><code>HWADDR=08:00:27:4E:59:37 ### 网卡的 MAC 地址
TYPE=Ethernet ### 连接类型
BOOTPROTO=static ### 这代表着该网卡指定了一个静态地址。
					  ### 如果这个值指定为 dhcp，这个网卡会从 DHCP 服务器获取 IP 地址，并且就不应该出现以下两行。
IPADDR=192.168.0.18
NETMASK=255.255.255.0
GATEWAY=192.168.0.1
NM_CONTROLLED=no ### 应该给以太网卡设置，以便可以让 NetworkManager 可以修改这个文件。
NAME=enp0s3
UUID=14033805-98ef-4049-bc7b-d4bea76ed2eb
ONBOOT=yes ### 操作系统会在启动时打开这个网卡。
</code></pre><h3 id="设定主机名" tabindex="-1">设定主机名 <a class="header-anchor" href="#设定主机名" aria-label="Permalink to “设定主机名”">​</a></h3><p>在 RHEL 7 中， <code>hostnamectl</code> 命令被同时用来查询和设定系统的主机名。</p><p>要展示当前的主机名，输入：</p><pre><code># hostnamectl status
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-System-hostname.png" alt="在RHEL 7 中检查系统的主机名"></p><p><em>检查系统的主机名</em></p><p>要更改主机名，使用</p><pre><code># hostnamectl set-hostname [new hostname]
</code></pre><p>例如，</p><pre><code># hostnamectl set-hostname cinderella
</code></pre><p>要想使得更改生效，你需要重启 hostnamed 守护进程（这样你就不必因为要应用更改而登出并再登录系统）：</p><pre><code># systemctl restart systemd-hostnamed
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Set-System-Hostname.png" alt="在 RHEL7 中设定系统主机名"></p><p><em>设定系统主机名</em></p><p>另外， RHEL 7 还包含 <code>nmcli</code> 工具，它可被用来达到相同的目的。要展示主机名，运行：</p><pre><code># nmcli general hostname
</code></pre><p>且要改变主机名，则运行：</p><pre><code># nmcli general hostname [new hostname]
</code></pre><p>例如，</p><pre><code># nmcli general hostname rhel7
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/nmcli-command.png" alt="使用 nmcli 命令来设定主机名"></p><p><em>使用 nmcli 命令来设定主机名</em></p><h3 id="在开机时开启网络服务" tabindex="-1">在开机时开启网络服务 <a class="header-anchor" href="#在开机时开启网络服务" aria-label="Permalink to “在开机时开启网络服务”">​</a></h3><p>作为本文的最后部分，就让我们看看如何确保网络服务在开机时被自动开启。简单来说，这个可通过创建符号链接到某些由服务的配置文件中的 <code>[Install]</code> 小节中指定的文件来实现。</p><p>以 firewalld（/usr/lib/systemd/system/firewalld.service） 为例：</p><pre><code>[Install]
WantedBy=basic.target
Alias=dbus-org.fedoraproject.FirewallD1.service
</code></pre><p>要开启该服务，运行：</p><pre><code># systemctl enable firewalld
</code></pre><p>另一方面，要禁用 firewalld，则需要移除符号链接：</p><pre><code># systemctl disable firewalld
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Enable-Service-at-System-Boot.png" alt="在开机时开启服务"></p><p><em>在开机时开启服务</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这篇文章中，我们总结了如何安装 SSH 及使用它安全地连接到一个 RHEL 服务器；如何改变主机名，并在最后如何确保在系统启动时开启服务。假如你注意到某个服务启动失败，你可以使用 <code>systemctl status -l [service]</code> 和 <code>journalctl -xn</code> 来进行排错。</p><p>请随意使用下面的评论框来让我们知晓你对本文的看法。提问也同样欢迎。我们期待着你的反馈！</p><hr>`,70)),s("p",null,[e[5]||(e[5]=t("via: ",-1)),o(n,{href:"http://www.tecmint.com/rhcsa-series-secure-ssh-set-hostname-enable-network-services-in-rhel-7/"},{default:p(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/rhcsa-series-secure-ssh-set-hostname-enable-network-services-in-rhel-7/",-1)])]),_:1})]),s("p",null,[e[9]||(e[9]=t("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[6]||(e[6]=[t("Gabriel Cánepa",-1)])]),_:1}),e[10]||(e[10]=t(" 译者：",-1)),o(n,{href:"https://github.com/FSSlc"},{default:p(()=>[...e[7]||(e[7]=[t("FSSlc",-1)])]),_:1}),e[11]||(e[11]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[14]||(e[14]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原创翻译，",-1)),o(n,{href:"https://linux.cn/"},{default:p(()=>[...e[13]||(e[13]=[t("Linux中国",-1)])]),_:1}),e[16]||(e[16]=t(" 荣誉推出",-1))])])}const A=a(i,[["render",m]]);export{f as __pageData,A as default};
